import { FilterConfig } from '../types';
import { validateBrandsInCountry } from '../utils';

export const watchTowerBrandFilterConfig: FilterConfig = {
  key: 'watch_tower_brand',
  order: 52,
  isCommon: true,
  parentKey: 'country',
  calculator: () => null,
  validator: (filterData, value, currentApplied) => {
    if (value === null) return true;

    return validateBrandsInCountry(
      'watch_tower_brands',
      filterData,
      String(currentApplied?.country),
      String(value),
    );
  },
  contextualValidator: (dataFilters, country, brand) => {
    return validateBrandsInCountry(
      'watch_tower_brands',
      dataFilters,
      String(country),
      String(brand),
    );
  },
  dependentDefaultCascadingCalculator: (filterData, currentValues) => {
    const watchTowerBrand = currentValues.watch_tower_brand;
    if (!watchTowerBrand) return null;

    if (
      validateBrandsInCountry(
        'watch_tower_brands',
        filterData,
        String(currentValues.country),
        String(watchTowerBrand),
      )
    ) {
      return watchTowerBrand;
    }

    return null;
  },
  dependencies: [],
  metadata: {
    displayName: 'Watch Tower Brand',
    description: 'Watch Tower brand filter, depends on selected country',
  },
};
